WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id, page ORDER BY event_time DESC NULLS FIRST, id) AS rn FROM web_events QUALIFY rn = 1) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, s.rn, (SELECT AVG(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS avg_web_event_duration_sec FROM ranked s ORDER BY duration_sec DESC, id;
